using System.Linq;
using Aethvirse.Skills;
using Aethvirse.Stats;
using NUnit.Framework;
using UnityEditor;

namespace Aethvirse.Tests
{
    /// <summary>The Paladin class asset (generated by ClassDataBuilder from the Godot data).</summary>
    public sealed class PaladinDataTests
    {
        const string Path = "Assets/Data/Classes/Paladin.asset";
        ClassData _c;

        [SetUp]
        public void SetUp()
        {
            _c = AssetDatabase.LoadAssetAtPath<ClassData>(Path);
            Assert.That(_c, Is.Not.Null, $"missing {Path}");
        }

        [Test]
        public void HasSixActivesThreePassivesOneUltimate()
        {
            Assert.That(_c.skills.Count(s => !s.IsPassive), Is.EqualTo(6));
            Assert.That(_c.skills.Count(s => s.IsPassive), Is.EqualTo(3));
            Assert.That(_c.skills.Count(s => s.isUltimate), Is.EqualTo(1));
        }

        [Test]
        public void DamagingSkillsHaveATimelineAndADistinctLook()
        {
            var actives = _c.skills.Where(s => !s.IsPassive).ToList();
            foreach (SkillData s in actives)
            {
                if (s.kind != SkillKind.Buff) Assert.That(s.attack, Is.Not.Null, s.id);
                Assert.That(s.fx, Is.Not.EqualTo(SkillFxKind.None), s.id);
            }
            Assert.That(actives.Select(s => s.fx).Distinct().Count(), Is.EqualTo(actives.Count), "every active skill looks different");
        }

        [Test]
        public void SkillCombosReferenceRealSkills()
        {
            Assert.That(_c.skillCombos.Count, Is.EqualTo(3));
            foreach (SkillComboData combo in _c.skillCombos)
            {
                Assert.That(_c.FindSkill(combo.first), Is.Not.Null, combo.id);
                Assert.That(_c.FindSkill(combo.second), Is.Not.Null, combo.id);
            }
        }

        [Test]
        public void StartsWithTwoSkillsAtLevelOne() =>
            Assert.That(_c.skills.Count(s => s.unlockLevel <= 1), Is.EqualTo(2));
    }
}
